import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------
# CUDA source: half‑precision LayerNorm (affine) with warp‑level reductions
# ------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef BLOCK_SIZE
#define BLOCK_SIZE 256            // must be multiple of 32
#endif

// warp‑level reduction of a float value using shuffle
__inline__ __device__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = warpSize/2; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

// ------------------------------------------------------------
template <int BLOCK_THREADS>
__global__ void layernorm_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int batch,
    int N,
    float eps)
{
    // one block per sample (batch element)
    const int b = blockIdx.x;
    if (b >= batch) return;

    const int lane   = threadIdx.x % warpSize;          // thread lane inside warp
    const int warpId = threadIdx.x / warpSize;          // warp index in block
    const int numWarps = BLOCK_THREADS / warpSize;

    // -----------------------------------------------------------------
    // 1) compute mean and variance (two‑pass reduction using shuffles)
    // -----------------------------------------------------------------
    float sum   = 0.f;
    float sumsq = 0.f;

    // each thread processes a strided chunk of the N elements
    for (int i = threadIdx.x; i < N; i += BLOCK_THREADS) {
        float v = __half2float(input[b * N + i]);
        sum   += v;
        sumsq += v * v;
    }

    // ---- intra‑warp reduction ----
    sum   = warp_reduce_sum(sum);
    sumsq = warp_reduce_sum(sumsq);

    // ---- inter‑warp reduction via shared memory ----
    __shared__ float warp_sum[BLOCK_SIZE / 32];
    __shared__ float warp_sumsq[BLOCK_SIZE / 32];
    if (lane == 0) {
        warp_sum[warpId]   = sum;
        warp_sumsq[warpId] = sumsq;
    }
    __syncthreads();

    // first warp finishes the reduction
    float block_sum = 0.f;
    float block_sumsq = 0.f;
    if (warpId == 0) {
        if (lane < numWarps) {
            block_sum   = warp_sum[lane];
            block_sumsq = warp_sumsq[lane];
        }
        // reduce across the numWarps entries
        block_sum   = warp_reduce_sum(block_sum);
        block_sumsq = warp_reduce_sum(block_sumsq);
        if (lane == 0) {
            warp_sum[0]   = block_sum;   // reuse shared array to hold final results
            warp_sumsq[0] = block_sumsq;
        }
    }
    __syncthreads();

    // broadcast mean & inv_std to all threads in the block
    const float mean = warp_sum[0] / static_cast<float>(N);
    const float var  = warp_sumsq[0] / static_cast<float>(N) - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    // -----------------------------------------------------------------
    // 2) normalize, apply affine transformation
    // -----------------------------------------------------------------
    for (int i = threadIdx.x; i < N; i += BLOCK_THREADS) {
        const int idx = b * N + i;
        float x = __half2float(input[idx]);
        float y = (x - mean) * inv_std;               // normalize

        // weight & bias are per‑element (same shape as normalized dims)
        float w = __half2float(weight[i]);
        float b_i = __half2float(bias[i]);

        float out = y * w + b_i;
        output[idx] = __float2half(out);
    }
}

// ------------------------------------------------------------
torch::Tensor layernorm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps)
{
    // ensure contiguous half‑precision tensors
    input  = input.contiguous();
    weight = weight.contiguous();
    bias   = bias.contiguous();

    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16, "weight must be float16");
    TORCH_CHECK(bias.dtype()   == torch::kFloat16, "bias must be float16");

    auto out = torch::empty_like(input);

    const int batch = input.size(0);
    const int N = input.numel() / batch;   // elements per sample

    const dim3 grid(batch);
    const dim3 block(BLOCK_SIZE);

    // launch templated kernel (BLOCK_SIZE known at compile time)
    layernorm_kernel<BLOCK_SIZE><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<const __half*>(bias.data_ptr()),
        reinterpret_cast<__half*>(out.data_ptr()),
        batch, N, eps);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in layernorm kernel: ", cudaGetErrorString(err));
    }
    return out;
}
"""

# ------------------------------------------------------------
# C++ declaration for the binding
cpp_source = "torch::Tensor layernorm_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps);"

# Compile the extension
layernorm_ext = load_inline(
    name="layernorm_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["layernorm_cuda"],
    verbose=False,
)

# ------------------------------------------------------------
# PyTorch Module exposing the custom LayerNorm
# ------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Half‑precision LayerNorm (affine=True) matching torch.nn.LayerNorm.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super().__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps

        # learnable parameters, same init as torch.nn.LayerNorm
        self.weight = nn.Parameter(torch.ones(normalized_shape, dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(normalized_shape, dtype=torch.float16))

        self._ln = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure half precision & contiguity
        x = x.to(torch.float16).contiguous()
        return self._ln.layernorm_cuda(x, self.weight, self.bias, self.eps)

# ------------------------------------------------------------
# Example usage (mirrors the reference test harness)
# ------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256

    model = ModelNew((features, dim1, dim2))
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    y = model(x)
    print(y.shape, y.dtype)
